## Submitted testbench
```systemverilog
module tb;
  // -------------------------------------------------------------
  // Parameters and clock generation
  // -------------------------------------------------------------
  localparam int CLK_PERIOD = 8; // 125 MHz
  reg clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  // -------------------------------------------------------------
  // Reset and configuration
  // -------------------------------------------------------------
  reg rst = 1'b1;
  reg [15:0] prescale = 16'd5;
  reg rxd = 1'b1;                     // UART receive line

  // AXI‑Stream inputs (not used)
  reg [7:0] s_axis_tdata = '0;
  reg       s_axis_tvalid = 1'b0;

  // DUT output signals
  wire [7:0] m_axis_tdata;
  wire       m_axis_tvalid;
  wire       txd;
  wire       tx_busy;
  wire       rx_busy;
  wire       rx_overrun_error;
  wire       rx_frame_error;
  wire       s_axis_tready;           // unused top‑level output

  // -------------------------------------------------------------
  // DUT instantiation (default parameters, DATA_WIDTH = 8)
  // -------------------------------------------------------------
  uart #(.DATA_WIDTH(8)) dut (
    .clk               (clk),
    .rst               (rst),
    .s_axis_tdata      (s_axis_tdata),
    .s_axis_tvalid     (s_axis_tvalid),
    .s_axis_tready     (s_axis_tready), // unused
    .txd               (txd),
    .tx_busy           (tx_busy),
    .rx_busy           (rx_busy),
    .rx_overrun_error  (rx_overrun_error),
    .rx_frame_error    (rx_frame_error),
    .prescale          (prescale),
    .rxd               (rxd),
    .m_axis_tdata      (m_axis_tdata),
    .m_axis_tvalid     (m_axis_tvalid),
    .m_axis_tready     (1'b0)            // keep low (no handshake)
  );

  // -------------------------------------------------------------
  // Reset sequencing
  // -------------------------------------------------------------
  initial begin
    #100;
    rst = 1'b0;
    #100;
    rst = 1'b1;
    #100;
    rst = 1'b0;
    #100;
  end

  // -------------------------------------------------------------
  // Simple UART byte transmitter (drives rxd)
  // -------------------------------------------------------------
  task automatic send_byte(input byte unsigned b);
    int bit_clks = int'(prescale) * 8;
    // start bit
    rxd = 1'b0;
    repeat (bit_clks) @(posedge clk);
    // data bits, LSB first
    for (int i = 0; i < 8; i++) begin
      rxd = b[i];
      repeat (bit_clks) @(posedge clk);
    end
    // stop bit
    rxd = 1'b1;
    repeat (bit_clks) @(posedge clk);
  endtask

  // -------------------------------------------------------------
  // Stimulus: three back‑to‑back frames, first data = 8'h5A
  // -------------------------------------------------------------
  initial begin
    // wait a couple of clocks after reset
    @(posedge clk);
    @(posedge clk);

    // Frame 1: data = 8'h5A (will be held in m_axis_tdata)
    send_byte(8'h5A);

    // Frame 2: any payload
    send_byte(8'h11);

    // Frame 3: any payload
    send_byte(8'h22);

    // Allow time for the coverage point to be observed
    #2000;
    $finish;
  end

endmodule
```

